use std::{fs,collections::{BTreeMap,BTreeSet},os::unix::fs::MetadataExt};use serde_json::{Value,json};use sha2::{Sha256,Digest};
const R:&str="/home/ubuntu/src/zopro-perf-work/two-bank-caller177";
fn read(p:&str)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:&str)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn med(mut x:Vec<f64>)->f64{x.sort_by(f64::total_cmp);assert!(x.len()%2==1);x[x.len()/2]}
fn main(){let mut count=0;for f in["build-pins.json","capture-pins.json"]{let pins=read(&format!("{R}/{f}"));for(p,h)in pins.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap(),"{p}");count+=1;}}
let backs=read(&format!("{R}/backings.json"));let mut inodes=BTreeSet::new();for b in backs.as_array().unwrap(){let p=b["path"].as_str().unwrap();let m=fs::metadata(p).unwrap();assert_eq!(m.ino(),b["ino"].as_u64().unwrap());assert_eq!(m.dev(),b["dev"].as_u64().unwrap());assert_eq!(m.len(),b["size"].as_u64().unwrap());assert_eq!(hash(p),b["sha256"].as_str().unwrap());assert_eq!(b["sha256"],backs[0]["sha256"]);assert!(inodes.insert((m.dev(),m.ino())));}
let mut rows=BTreeMap::<String,Value>::new();let mut samples=0;let mut elapsed=0.;let mut pre_elapsed=0.;let mut input=None;
for name in["preflight","capture"]{let plan=read(&format!("{R}/{name}-plan.json"));let run=read(&format!("{R}/{name}-run/result.json"));assert_eq!(run["status"],"complete");let mut names=Vec::new();for step in plan["steps"].as_array().unwrap(){let n=step["name"].as_str().unwrap();names.push(n.to_string());let d=format!("{R}/{name}-run/{n}");let e=read(&format!("{d}/exit.json"));assert_eq!(e["returncode"],0);assert_eq!(e["success"],true);for stream in["stdout","stderr"]{assert_eq!(hash(&format!("{d}/{stream}.log")),e[format!("{stream}_sha256")].as_str().unwrap());}let cmd=read(&format!("{d}/command.json"));assert_eq!(&cmd["argv"].as_array().unwrap()[4..],step["argv"].as_array().unwrap());for(k,v)in cmd["environment"].as_object().unwrap(){assert_eq!(&step["environment"][k],v);}
let r=read(&format!("{d}/stdout.log"));let rounds=if name=="capture"{17}else{1};assert_eq!(r["rounds"],rounds);assert_eq!(r["primes"],3);assert_eq!(r["all_outputs_checked"],true);assert_eq!(r["immutable_inputs"],true);assert_eq!(r["new_proofs"],0);assert_eq!(r["samples_ns"].as_array().unwrap().len(),rounds as usize);assert_eq!(r["workers"].as_u64().unwrap().to_string(),step["argv"][1]);assert_eq!(r["arm"],step["argv"][2]);let w=r["workers"].as_u64().unwrap()as usize;let want:Vec<_>=(0..w).map(|i|if w==1{2}else{i}).collect();assert_eq!(r["worker_cpus"],json!(want));if let Some(ref v)=input{assert_eq!(&r["input_digest"],v)}else{input=Some(r["input_digest"].clone());}samples+=rounds;
if name=="capture"{elapsed+=e["elapsed_ms"].as_f64().unwrap();rows.insert(n.into(),r);}else{pre_elapsed+=e["elapsed_ms"].as_f64().unwrap();}
}assert_eq!(run["steps"],json!(names));}
assert_eq!(samples,924);assert_eq!(rows.len(),54);let mut summary=Vec::new();let mut all_pairs=Vec::new();for w in[1,16,32]{let mut times=[Vec::new(),Vec::new()];let mut cpu=[Vec::new(),Vec::new()];let mut rss=[0.;2];let mut ratios=Vec::new();let mut per_copy=Vec::new();let mut wins=0;let mut faults=[0u64;2];for copy in 0..3{let mut copy_ratios=Vec::new();for block in 0..3{let mut means=[0.;2];for(i,arm)in["OFF","ON"].into_iter().enumerate(){let r=&rows[&format!("b{block}-copy{copy}-w{w}-{arm}")];means[i]=r["samples_ns"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as f64/1e6).sum::<f64>()/17.;times[i].push(means[i]);let u=&r["usage"];cpu[i].push((u["user_cpu_ms"].as_f64().unwrap()+u["system_cpu_ms"].as_f64().unwrap())/17.);let peak=u["whole_process_maxrss_kib"].as_f64().unwrap()/1024.;if peak>rss[i]{rss[i]=peak;}faults[i]+=u["major_faults"].as_u64().unwrap();}let ratio=means[1]/means[0];ratios.push(ratio);copy_ratios.push(ratio);wins+=usize::from(ratio<1.);all_pairs.push(json!({"workers":w,"backing":copy,"block":block,"off_ms":means[0],"on_ms":means[1],"ratio":ratio}));}per_copy.push(med(copy_ratios));}
let decision=if per_copy.iter().all(|r|*r<1.){"select short verified SDK screen"}else if per_copy.iter().all(|r|*r>1.){"close recipe for this context"}else{"inconclusive backing signs"};let r=json!({"workers":w,"off_ms":med(times[0].clone()),"on_ms":med(times[1].clone()),"paired_ratio_median":med(ratios.clone()),"paired_ratio_min":ratios.iter().copied().reduce(f64::min).unwrap(),"paired_ratio_max":ratios.iter().copied().reduce(f64::max).unwrap(),"per_backing_median_ratios":per_copy,"wins":wins,"pairs":9,"off_cpu_ms":med(cpu[0].clone()),"on_cpu_ms":med(cpu[1].clone()),"off_peak_rss_mib":rss[0],"on_peak_rss_mib":rss[1],"major_faults":faults,"decision":decision});println!("{}",r);summary.push(r);}
let out=json!({"review_passed":true,"pins_checked":count,"distinct_equal_byte_backings":3,"all_1104_caller_outputs_checked":true,"timed_samples":samples,"main_samples":918,"capture_command_elapsed_ms":elapsed,"preflight_command_elapsed_ms":pre_elapsed,"summary":summary,"pairs":all_pairs,"new_proofs":0,"accepted_source_changed":false,"SDK_performance_measured":false,"AWS_performance_measured":false});fs::write(format!("{R}/analysis.json"),serde_json::to_vec_pretty(&out).unwrap()).unwrap();println!("Review PASS: {samples} timed calls; {:.3}s capture command time",elapsed/1000.);}
